    for i in range(H):
        for j in range(W):
            if not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=True; comp=[]
                while stack:
                    a,b=stack.pop(); comp.append((a,b))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dy,b+dx
                        if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==g[a][b]:
                            seen[x][y]=True; stack.append((x,y))
                comps.append(comp)
    out=[r[:] for r in g]
    def nbcol(x,y):
        cnt=Counter()
        for dy in(-1,0,1):
            for dx in(-1,0,1):
                if dy==dx==0: continue
                x2,y2=x+dy,y+dx
                if 0<=x2<H and 0<=y2<W: cnt[g[x2][y2]]+=1
        return cnt
    for comp in comps:
