import numpy as np
# variant loop: tie-break options, isolation criteria
def make_f(mode_noise='isolated', tiebreak='first'):
    if mode_noise=='threshold':
        def compmax(A,H,W,color):
            seen=np.zeros_like(A,bool); best=0
            for i in range(H):
                for j in range(W):
                    if A[i,j]==color and not seen[i,j]:
                        st=[(i,j)]; seen[i,j]=True; c=[]
                        while st:
                            x,y=st.pop(); c.append((x,y))
                            for dx in(-1,0,1):
                                for dy in(-1,0,1):
                                    nx,ny=x+dx,y+dy
                                    if 0<=nx<H and 0<=ny<W and not seen[nx,ny] and A[nx,ny]==color:
                                        seen[nx,ny]=True; st.append((nx,ny))
                        if len(c)>best: best=len(c)
            return best
    else:
        pass
    tbo={}
    if tiebreak=='first': tbo['mode']={'fn':lambda nb,cnt,idx: cnt.argsort()[::-1][idx[0]],'name':'first_of_mode'}
    if tiebreak=='min':   tbo['mode']={'fn':lambda nb,cnt,idx:int(np.where(cnt==cnt.max())[0].min()),'name':'min_id'}
    def f(A,S=None,tb=tiebreak):
        A=np.array(A,dtype=int); H,W=A.shape; out=A.copy()
        if S is None:
            nset={c for c in set(A.flatten()) if max(compmax(A,H,W,int(c)))<3}
        else:
            def mk():
                mc={}
                for c in set(A.flatten()): mc[c]=max(compmax(A,H,W,int(c)))
                return max(mc.values())
            S=mk()
            nset={c for c in set(A.flatten()) if max(compmax(A,H,W,int(c)))<S}
        idx=list(range(len(nset))); 
        while True:
            for i in range(H):
                for j in range(W):
                    v=int(A[i,j])
                    if v in nset:
                        nb=[int(A[x,y]) for x in range(max(0,i-1),min(H,i+2)) for y in range(max(0,j-1),min(W,j+2)) if (x,y)!=(i,j)]
                        cnt,_=np.unique(nb,return_counts=True); cnt=collections.Counter(nb)
                        top=[k for k,vv in cnt.items() if vv==max(cnt.values())]
                        out[i,j]=tbo[tb](nb,top)[0]
            nset={c for c in nset if False}|{c for c in set(out.flatten()) if int(c) not in nset}
        return out.tolist()
    return f

