def f(A,S=None):
    A=np.array(A,dtype=int); H,W=A.shape; out=A.copy()
    noise=set()
    if S is None:
        noise={int(c) for c in set(A.flatten()) if compmax(A,H,W,int(c))<3}
    else:
        for c in set(A.flatten()):
            if compmax(A,H,W,int(c))<S: noise.add(int(c))
    nset=list(noise)
    nbw=[[lambda i_,j_: [int(A[x,y]) for x in range(max(0,i_)-1,min(H,i_)+2) for y in range(max(0,j_)-1,min(W,j_)+2) if (x,y)!=(i_,j_)](i_,j_) ] for _ in [0]]
    for i in range(H):
        for j in range(W):
            v=int(A[i,j])
            if v in noise:
                nb=[int(A[x,y]) for x in range(max(0,i-1),min(H,i+2)) for y in range(max(0,j-1),min(W,j+2)) if (x,y)!=(i,j)]
                cnt=collections.Counter(nb)
                # exclude noise colors from counts
                ccnt={k:v for k,v in cnt.items() if k not in noise}
